[ExtensionOf(formControlStr(LedgerAllocationRequest, AVACopyToCostAllocationJournal))]
internal final class AVALedgerAllocationRequestFrmCopyToCostAllocationJournalCtrl_Extension
{
}

Method.Source:
/// <summary>
/// Extension of the method <m>modified</m>
/// </summary>
/// <returns>boolean</returns>
public boolean modified()
{
    boolean ret;

    ret = next modified();
    FormCheckBoxControl fc = this;
    FormComboBoxControl editProcessOptions_bec = fc.formRun().design().controlName(formControlStr(LedgerAllocationRequest, editProcessOptions));
    FormCheckBoxControl postCostAllocationJournal_bec = fc.formRun().design().controlName(formControlStr(LedgerAllocationRequest, AVAPostCostAllocationJournal));
    FormCheckBoxControl summarizeValues_bec =  fc.formRun().design().controlName(formControlStr(LedgerAllocationRequest, AVASummarizeValues));
    if (fc.checked())
    {
        editProcessOptions_bec.selection(LedgerAllocationProcessMode::ProposalOnly);
        editProcessOptions_bec.enabled(false);
        postCostAllocationJournal_bec.enabled(true);
        summarizeValues_bec.enabled(true);
    }
    else
    {
        editProcessOptions_bec.enabled(true);
        postCostAllocationJournal_bec.enabled(false);
        postCostAllocationJournal_bec.checked(false);
        summarizeValues_bec.enabled(false);
        summarizeValues_bec.checked(false);
    }

    return ret;
}
